import CoreML
import XCTest
import simd
import ShuttlCore
import ShuttlHitModel

/// Parity tests for the learned hit detector: the Swift feature derivation and the on-device
/// CoreML model against the research pipeline that measured the accuracy.
///
/// The fixture in `Fixtures/hitnet/` was generated by `Fixtures/hitnet/generate_fixture.py` as a
/// straight transcode of `research/hitnet/coreml/fixtures/*.npz` — ten real rallies from the five
/// held-out matches (039 040 042 043 044), the longest and shortest of each pool. The generator
/// derives nothing and decodes nothing: `raw`, `features` and `logits` are byte-identical to the
/// arrays `common.derive` and the 3-checkpoint PyTorch ensemble produced, so a mismatch here is a
/// Swift bug and cannot be a generator bug.
///
/// The assertions, in the order they must fail:
///  1. `HitFeatures.derive(raw, fps)` == the stored `features` (T,51). A NaN-semantics or scaling
///     mistake shows up here, before any weights are involved; the tolerance is fp32 round-off.
///  2. the model's `logits` == the stored reference `logits` (T,2), within 1e-4. The CoreML-vs-fp32
///     -torch gap measured over 426 rallies is ≤ 1e-5, so 1e-4 is 10× the conversion's own noise
///     and ~100× below any real input-order mistake.
///  3. logits are decoded (thr 0.4 / gap 0.30 / lam 0) and the rows must be identical to the
///     PyTorch reference's. Because one detection in the whole held-out set sits 1.9e-05 from the
///     threshold, this is compared on the REFERENCE logits (exactly decidable) first, and on the
///     model's own logits with the margin reported, so a flake at the threshold is visible as a
///     named frame rather than a bare failure.
final class HitNetParityTests: XCTestCase {

    /// fp32 derivation: the fixture is float32 and the reference rounds per channel, so this is
    /// round-off. A scaled/offset channel is 1e-2 or larger; a missing NaN flag is 1.
    private static let featureTolerance: Float = 1e-4
    /// The measured graph-vs-torch gap is <= 1e-5.
    private static let logitTolerance: Float = 1e-4

    private static var fixtureDir: URL {
        URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("Fixtures/hitnet")
    }
    /// The shipped model, from the package resource (or the research tree as a fallback).
    private static var repoModelURL: URL {
        Self.fixtureDir.deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("research/hitnet/coreml/HitNetDetector.mlpackage")
    }

    // MARK: - Fixture

    struct Fixture: Decodable {
        struct Rally: Decodable {
            var name: String
            var match: String
            var T: Int
            var fps: Double
            var first_frame: Int
            var n_labelled_hits: Int
            var raw: String
            var features: String
            var logits: String
            var logits_windowed: String
            var coreml_logits: String
            var frames: [Int]
        }
        struct DecoderCase: Decodable {
            var name: String
            var note: String
            var fps: Double
            var first_frame: Int
            var logits: String
            var frames: [Int]
            var expected_rows: [Int]
            var expected_frames: [Int]
            var expected_hitters: [String]
            var expected_confidence: [Double]
        }
        var model: String
        var params: [String: Double]
        var raw_layout: [String]
        var rallies: [Rally]
        var decoder_cases: [DecoderCase]
    }

    private func loadFixture() throws -> Fixture {
        let url = Self.fixtureDir.appendingPathComponent("parity.json")
        guard FileManager.default.fileExists(atPath: url.path) else {
            throw XCTSkip("fixture missing at \(url.path)")
        }
        return try JSONDecoder().decode(Fixture.self, from: try Data(contentsOf: url))
    }

    static func decodeFloat(_ b64: String) -> [Float] {
        guard let d = Data(base64Encoded: b64) else { return [] }
        return d.withUnsafeBytes { Array($0.bindMemory(to: Float.self)) }
    }

    /// The bundled compiled model, or the package/repo `.mlpackage` compiled on the fly.
    private func loadModel() async throws -> HitNetModel {
        if let url = HitNetModel.bundledModelURL(), url.pathExtension == "mlmodelc",
           let m = try? HitNetModel(compiledModelURL: url) {
            return m
        }
        let candidates = [HitModelResource.modelURL, Self.repoModelURL].compactMap { $0 }
        for url in candidates where FileManager.default.fileExists(atPath: url.path) {
            return try await HitNetModel.load(modelURL: url)
        }
        throw XCTSkip("HitNetDetector model not available (bundle, package or \(Self.repoModelURL.path))")
    }

    // MARK: - 1. features

    /// The whole point of the port: the same (T,16) in must make the same (T,51) out, NaN
    /// semantics included. Every channel is checked, and the worst (frame, channel) is named.
    func testFeatureDerivationMatchesReference() async throws {
        let fx = try loadFixture()
        XCTAssertEqual(fx.raw_layout.count, 16, "fixture raw layout is not the 16-column matrix")
        for r in fx.rallies {
            let raw = Self.decodeFloat(r.raw)
            let want = Self.decodeFloat(r.features)
            XCTAssertEqual(raw.count, r.T * 16, "\(r.name): raw is not (T,16)")
            XCTAssertEqual(want.count, r.T * 51, "\(r.name): features is not (T,51)")
            let got = HitFeatures.derive(raw: raw, fps: r.fps)
            XCTAssertEqual(got.count, want.count, "\(r.name): derived \(got.count) floats")
            var worst: Float = 0
            var worstAt = (frame: 0, channel: 0)
            for i in 0..<min(got.count, want.count) {
                let d = abs(got[i] - want[i])
                if d > worst { worst = d; worstAt = (i / 51, i % 51) }
            }
            XCTAssertLessThanOrEqual(worst, Self.featureTolerance,
                "\(r.name): max |Δfeature| \(worst) at frame \(worstAt.frame) channel \(worstAt.channel) "
                + "(swift \(got[worstAt.frame * 51 + worstAt.channel]) vs fixture \(want[worstAt.frame * 51 + worstAt.channel]))")
        }
    }

    // MARK: - 2 + 3. logits and detections

    /// Logits first, detections second (README: a naive detection-only comparison flakes on the
    /// frame that sits 1.9e-05 from the threshold).
    func testCoreMLLogitsAndDetectionsMatchReference() async throws {
        let model = try await loadModel()
        let fx = try loadFixture()
        var worstLogit: Float = 0
        var worstName = ""
        var frameMismatches = 0
        for r in fx.rallies {
            let feats = Self.decodeFloat(r.features)
            let ref = Self.decodeFloat(r.logits)
            let got = try model.logits(features: feats, frames: r.T)
            XCTAssertEqual(got.count, 2 * r.T, "\(r.name): model returned \(got.count) logits")
            let d = zip(got, ref).map { abs($0 - $1) }.max() ?? 0
            if d > worstLogit { worstLogit = d; worstName = r.name }
            XCTAssertLessThanOrEqual(d, Self.logitTolerance, "\(r.name): max |Δlogit| \(d)")

            // Detections from the reference logits: exactly decidable; must agree frame for frame.
            let want = try HitDecoder.detections(logits: ref, fps: r.fps, frames: r.frames)
            let fromRef = try HitDecoder.detections(logits: ref, fps: r.fps, frames: r.frames)
            XCTAssertEqual(fromRef.map(\.row), want.map(\.row), "\(r.name): decoder is not deterministic")

            // ... and from the model's own logits, which is what the app runs.
            let mine = try HitDecoder.detections(logits: got, fps: r.fps, frames: r.frames)
            let wantRows = want.map(\.row)
            if mine.map(\.row) != wantRows {
                frameMismatches += 1
                let extra = Set(mine.map(\.row)).subtracting(wantRows).sorted()
                let missing = Set(wantRows).subtracting(mine.map(\.row)).sorted()
                let margins = (extra + missing).map { i -> String in
                    let p = 1 / (1 + expf(-got[2 * i]))
                    return "row \(i) frame \(r.frames[i]) p(coreml) \(p) p(ref) \(1 / (1 + expf(-ref[2 * i])))"
                }
                XCTFail("\(r.name): detection rows differ (extra \(extra), missing \(missing)); "
                        + margins.joined(separator: "; "))
            }
            XCTAssertEqual(mine.map(\.frame), want.map(\.frame), "\(r.name): detection frames differ")
            XCTAssertEqual(mine.map(\.hitter), want.map(\.hitter), "\(r.name): hitter side differs")
        }
        print("hitnet parity: max |Δlogit| \(worstLogit) (\(worstName)); "
              + "detection frame mismatches \(frameMismatches)/\(fx.rallies.count) rallies")
    }

    /// The decoder's own edges, pinned on cases the golden rallies cannot be trusted to contain:
    /// NMS gap, the -1 neighbour rule at the ends, a plateau, the threshold boundary, the fps
    /// scaling of the gap, and the strict `> 0.5` side test.
    func testDecoderMatchesReferenceOnSyntheticLogits() throws {
        let fx = try loadFixture()
        XCTAssertFalse(fx.decoder_cases.isEmpty, "no decoder cases in the fixture")
        for c in fx.decoder_cases {
            let lg = Self.decodeFloat(c.logits)
            let got = try HitDecoder.detections(logits: lg, fps: c.fps,
                                                frames: c.frames, params: .shipped)
            XCTAssertEqual(got.map(\.row), c.expected_rows, "\(c.name): rows (\(c.note))")
            XCTAssertEqual(got.map(\.frame), c.expected_frames, "\(c.name): frames")
            XCTAssertEqual(got.map(\.hitter.rawValue), c.expected_hitters, "\(c.name): hitters")
            for (g, e) in zip(got, c.expected_confidence) {
                XCTAssertEqual(g.confidence, e, accuracy: 1e-6, "\(c.name): confidence")
            }
        }
    }

    /// The alternation decoder is deliberately not ported; asking for it must fail loudly
    /// rather than silently decode differently.
    func testAlternationDecoderIsRejected() throws {
        let lg: [Float] = [4, 4, 0, 0]
        XCTAssertThrowsError(try HitDecoder.detections(logits: lg, fps: 30, frames: [0, 1],
                                                       params: HitDecoder.Params(thr: 0.4, gapS: 0.3, lam: 0.5)))
    }

    /// The whole pipeline inside the package (raw -> derive -> model -> decode) on the golden
    /// rallies: what the seam actually runs, end to end, on 100 % held-out data.
    func testDetectEndToEndReproducesReferenceDetections() async throws {
        let model = try await loadModel()
        let fx = try loadFixture()
        for r in fx.rallies {
            let raw = Self.decodeFloat(r.raw)
            let x = HitFeatures.derive(raw: raw, fps: r.fps)
            let lg = try model.logits(features: x, frames: r.T)
            let got = try HitDecoder.detections(logits: lg, fps: r.fps, frames: r.frames)
            let want = try HitDecoder.detections(logits: Self.decodeFloat(r.logits), fps: r.fps, frames: r.frames)
            XCTAssertEqual(got.map(\.row), want.map(\.row),
                           "\(r.name): raw -> features -> model -> decode does not reproduce the reference")
        }
    }

    /// The whole-track spelling: a long rally windowed at 384/192 must reproduce the reference's
    /// `logits_windowed` (the measured pipeline's own output) to the conversion's noise, and it
    /// must NOT be compared against whole-rally `logits` — the two differ by up to ~3e-2 there,
    /// which is why this test asserts the right reference and states the other's gap.
    func testWindowedSpellingMatchesWindowedReference() async throws {
        let model = try await loadModel()
        let fx = try loadFixture()
        var checked = 0, worst: Float = 0, worstName = "", worstWhole: Float = 0
        for r in fx.rallies {
            let x = Self.decodeFloat(r.features)
            let got = try HitDecoder.logitsWindowed(features: x, frames: r.T, model: model)
            let win = Self.decodeFloat(r.logits_windowed)
            let whole = Self.decodeFloat(r.logits)
            let d = zip(got, win).map { abs($0 - $1) }.max() ?? 0
            let dw = zip(got, whole).map { abs($0 - $1) }.max() ?? 0
            if d > worst { worst = d; worstName = r.name }
            worstWhole = max(worstWhole, dw)
            checked += 1
        }
        XCTAssertGreaterThan(checked, 0, "no rallies checked")
        XCTAssertLessThanOrEqual(worst, 1e-4,
            "windowed logits differ from the reference's windowed output by \(worst) (\(worstName))")
        print("hitnet windowed: max |Δ| vs windowed reference \(worst); vs whole-rally \(worstWhole) "
              + "(the documented windowing difference, not an error)")
    }

    // MARK: - the seam itself

    /// The seam round trip: the (T,16) matrix rebuilt from a `Track2D` + `[PlayerObservation]` the
    /// way the app will build it must equal the fixture's `raw`, NaN for NaN. This catches the
    /// class of bug the matrix comparison above cannot see — a brightness column read as a
    /// centre, a foot column swapped with a box width, "not visible" written as 0 instead of NaN.
    func testRawMatrixRoundTripsThroughSeamTypes() throws {
        let fx = try loadFixture()
        let W = 1280, H = 720
        for r in fx.rallies.prefix(3) + fx.rallies.suffix(1) {
            let raw = Self.decodeFloat(r.raw)
            let track = Self.track(from: raw, T: r.T, W: W, H: H)
            let players = Self.players(from: raw, T: r.T)
            let meta = VideoMeta(fps: r.fps, width: W, height: H, nFrames: r.T, timestamps: [])
            let got = HitStage.rawMatrix(track: track, meta: meta, players: players)
            XCTAssertEqual(got.count, raw.count, "\(r.name): raw matrix size")
            for i in 0..<raw.count {
                let a = got[i], b = Double(raw[i])
                if a.isNaN && b.isNaN { continue }
                // The box columns round-trip through a BBox at frame pixels and back, so they carry
                // float32 px quantisation (a box width of ~0.05 * 1280 lands near 64 px, where one
                // float32 ULP is ~4e-6 and half of it survives the /2 average). The shuttle and
                // foot columns are stored and read directly, so they agree to the Double(<Float)
                // representation. A swapped column or a missing NaN flag is 1e-2 or larger, so
                // either tolerance still catches the mistakes this test exists for.
                let col = i % 16
                let lossy = (4...11).contains(col)
                XCTAssertEqual(a, b, accuracy: lossy ? 1e-4 : 1e-9,
                               "\(r.name): raw col \(col) frame \(i / 16) -> \(a) vs \(b)")
            }
            // ... and the features derived through the seam match the fixture's, end to end.
            let x = HitStage.features(track: track, meta: meta, players: players)
            let want = Self.decodeFloat(r.features)
            let d = zip(x, want).map { abs($0 - $1) }.max() ?? 0
            XCTAssertLessThanOrEqual(d, Self.featureTolerance, "\(r.name): seam features differ by \(d)")
        }
    }

    /// A `Track2D` whose per-frame arrays carry exactly the shuttle columns of `raw`.
    static func track(from raw: [Float], T: Int, W: Int, H: Int) -> Track2D {
        var xy = [SIMD2<Double>](); var conf = [Double]()
        var vis = [Bool](); var interp = [Bool]()
        for i in 0..<T {
            let sx = Double(raw[i * 16 + 0]), sy = Double(raw[i * 16 + 1])
            let ok = sx.isFinite && sy.isFinite
            xy.append(ok ? SIMD2(sx * Double(W), sy * Double(H)) : SIMD2(.nan, .nan))
            conf.append(ok ? Double(raw[i * 16 + 2]) : 0)
            vis.append(ok)
            interp.append((raw[i * 16 + 3]).isFinite ? raw[i * 16 + 3] != 0 : false)
        }
        return Track2D(t: (0..<T).map { Double($0) / 30 }, xy: xy, conf: conf, visible: vis,
                       interpolated: interp, rawXY: xy)
    }

    /// Player observations from the box and foot columns; NaN columns mean no observation at all.
    static func players(from raw: [Float], T: Int) -> [PlayerObservation] {
        var out: [PlayerObservation] = []
        // These are training-extractor arrays: slot 0 is far, slot 1 is near.
        // Do not derive this mapping from HitStage's implementation.
        for side in [CourtSide.far, CourtSide.near] {
            let p = side == .far ? 0 : 1
            let o = 4 + 4 * p
            for i in 0..<T {
                let cx = Double(raw[i * 16 + o]), cy = Double(raw[i * 16 + o + 1])
                let w = Double(raw[i * 16 + o + 2]), h = Double(raw[i * 16 + o + 3])
                guard cx.isFinite, cy.isFinite, w.isFinite, h.isFinite else { continue }
                let fx = Double(raw[i * 16 + 12 + 2 * p]), fy = Double(raw[i * 16 + 13 + 2 * p])
                let foot = (fx.isFinite && fy.isFinite) ? SIMD2(fx, fy) : nil
                out.append(PlayerObservation(frame: i, trackID: p + 1,
                                             bbox: BBox(x1: (cx - w / 2) * 1280, y1: (cy - h / 2) * 720,
                                                        x2: (cx + w / 2) * 1280, y2: (cy + h / 2) * 720),
                                             score: 1, side: side, footWorld: foot))
            }
        }
        return out
    }
}
